def parse_position(line, board):
    rest = line[len("position"):].strip()
    if rest.startswith("startpos"):
        board = chess.Board()
        rest = rest[len("startpos"):].strip()
        if rest.startswith("moves"):
            for u in rest[len("moves"):].strip().split():
                try:
                    board.push_uci(u)
                except ValueError:
                    break
        return board
    if rest.startswith("fen"):
        rest = rest[len("fen"):].strip()
        if " moves " in rest:
            fen_part, moves_part = rest.split(" moves ", 1)
        else:
            fen_part, moves_part = rest, ""
        try:
            board = chess.Board(fen_part.strip())
        except ValueError:
            return board
        for u in moves_part.strip().split():
            try:
                board.push_uci(u)
            except ValueError:
                break
        return board
    return board


def parse_go(line, board):
    max_depth = MAX_PLY
    soft = SOFT_LIMIT
    hard = HARD_LIMIT
    tokens = line.split()[1:]
    i = 0
    own_time = None
    own_inc = 0.0
    while i < len(tokens):
        t = tokens[i]
        if t == "depth" and i + 1 < len(tokens):
            try:
                max_depth = max(1, min(MAX_PLY, int(tokens[i + 1])))
            except ValueError:
                pass
            i += 2
        elif t == "movetime" and i + 1 < len(tokens):
            try:
                hard = max(0.05, int(tokens[i + 1]) / 1000.0 - 0.05)
                soft = hard * 0.7
            except ValueError:
                pass
            i += 2
        elif t in ("wtime", "btime", "winc", "binc") and i + 1 < len(tokens):
            try:
                ms = int(tokens[i + 1])
            except ValueError:
                ms = None
            if ms is not None:
                is_white = board.turn == chess.WHITE
                if (t == "wtime" and is_white) or (t == "btime" and not is_white):
                    own_time = ms / 1000.0
                if (t == "winc" and is_white) or (t == "binc" and not is_white):
                    own_inc = ms / 1000.0
            i += 2
        else:
            i += 1
    if own_time is not None:
        alloc = max(0.05, min(HARD_LIMIT, own_time / 24.0 + own_inc * 0.5))
        soft = min(soft, alloc * 0.7 + 0.05)
        hard = min(hard, alloc + 0.25)
    return max_depth, soft, hard


